WITH flattened_attrs AS (SELECT id, customer_id, attributes, ship_to.city AS ship_city, ARRAY_MAX(TRANSFORM(items, x -> x.price)) AS max_item_price, EXISTS(coupon_codes, c -> c LIKE 'W%') AS has_welcome_code, TRY_CAST(attributes['weight_kg'] AS DOUBLE) AS weight_kg FROM carts) SELECT CASE WHEN max_item_price >= 270 THEN 'PREMIUM' ELSE 'STANDARD' END AS max_item_price_tier, customer_id, ship_city, AVG(weight_kg) AS avg_weight_kg, COUNT(*) FILTER (WHERE ship_city = 'Chiang Mai') AS chiang_mai_rows, COUNT_IF(ship_city = 'Berlin') AS berlin_events, SIZE(COLLECT_SET(ship_city)) AS num_ship_cities, GROUPING(CASE WHEN max_item_price >= 270 THEN 'PREMIUM' ELSE 'STANDARD' END) AS grouping_level FROM flattened_attrs GROUP BY CUBE (CASE WHEN max_item_price >= 270 THEN 'PREMIUM' ELSE 'STANDARD' END, customer_id, ship_city) HAVING COUNT(*) FILTER (WHERE ship_city = 'Chiang Mai') >= 1 ORDER BY customer_id DESC;
